SELECT stddev(icustays.los) AS standard_deviation FROM patients JOIN icustays ON patients.subject_id = icustays.subject_id WHERE patients.gender = 'F' AND patients.anchor_age = 72 AND icustays.first_careunit = 'ICU' AND patients.anchor_year BETWEEN 67 AND 77 AND icustays.intime <= patients.edregtime AND icustays.outtime >= patients.edouttime AND EXISTS (SELECT 1 FROM diagnoses_icd WHERE diagnoses_icd.subject_id = patients.subject_id AND diagnoses_icd.icd_code IN ('E116', 'E117', 'E118', 'E119'));